import socket, time, sys

HOST = "robust"
PORT = 1337


class Conn:
    def __init__(self, host=HOST, port=PORT, timeout=5.0, verbose=True):
        self.sock = socket.create_connection((host, port), timeout=timeout)
        self.sock.settimeout(0.5)
        self.timeout = timeout
        self.verbose = verbose
        self.buf = b""
        self.log = []

    def _note(self, txt):
        self.log.append(txt)

    def recv_some(self, quiet=1.0):
        """Read whatever arrives until `quiet` seconds of silence."""
        out = b""
        deadline = time.time() + quiet
        while time.time() < deadline:
            try:
                chunk = self.sock.recv(4096)
            except socket.timeout:
                continue
            except OSError as e:
                self._note("recv OSError: %r" % (e,))
                break
            if not chunk:
                self._note("EOF (connection closed by peer)")
                break
            if self.verbose:
                print("[RECV] %r" % (chunk,), flush=True)
            out += chunk
            self.buf += chunk
            deadline = time.time() + quiet
        return out

    def recv_until(self, markers, quiet=1.0, hard_timeout=None, label=""):
        """Read until any marker bytes appear at end of buffer, or hard timeout."""
        if isinstance(markers, (bytes, str)):
            markers = [markers]
        markers = [m if isinstance(m, bytes) else m.encode() for m in markers]
        out = b""
        start = time.time()
        hard = hard_timeout if hard_timeout is not None else self.timeout
        while time.time() - start < hard:
            try:
                chunk = self.sock.recv(4096)
            except socket.timeout:
                if any(self.buf.endswith(m) for m in markers):
                    break
                continue
            except OSError as e:
                self._note("recv OSError: %r" % (e,))
                break
            if not chunk:
                self._note("EOF (connection closed by peer)")
                break
            if self.verbose:
                print("[RECV] %r" % (chunk,), flush=True)
            out += chunk
            self.buf += chunk
            if any(m in self.buf for m in markers):
                # give a tiny extra window in case more comes
                self.sock.settimeout(0.2)
                try:
                    while True:
                        more = self.sock.recv(4096)
                        if not more:
                            self._note("EOF (connection closed by peer)")
                            break
                        if self.verbose:
                            print("[RECV] %r" % (more,), flush=True)
                        out += more
                        self.buf += more
                except (socket.timeout, OSError):
                    pass
                finally:
                    self.sock.settimeout(0.5)
                break
        return out

    def send(self, data):
        if isinstance(data, str):
            data = data.encode()
        print("[SEND] %r" % (data,), flush=True)
        self.sock.sendall(data)

    def sendline(self, data):
        if isinstance(data, str):
            data = data.encode()
        self.send(data + b"\n")

    def close(self):
        try:
            self.sock.close()
        except OSError:
            pass


if __name__ == "__main__":
    c = Conn()
    print("connected")
    c.recv_until([b"> ", b"\n"], hard_timeout=4.0)
    print("--- done initial read ---")
    c.close()
