HOST, PORT = 'robust', 1337

def recv_until(s, markers, timeout=2.5, max_total=65536):
    """Read until one of markers (bytes) appears or timeout. Returns (data, which)."""
    data = b''
    end = time.time() + timeout
    while time.time() < end:
        try:
            s.settimeout(max(0.05, end - time.time()))
            d = s.recv(4096)
        except socket.timeout:
            break
        except Exception as e:
            data += ('<ERR %r>' % e).encode()
            break
        if not d:
            data += b'<EOF>'
            break
        data += d
        for m in markers:
            if m in data:
                return data, m
        if len(data) > max_total:
            break
    return data, None

def run(steps, label):
    print('='*20, label, '='*20)
    try:
        s = socket.create_connection((HOST, PORT), 5)
    except Exception as e:
        print('CONNECT FAIL', e); return
    try:
        d, m = recv_until(s, [b'choice: '], 5)
        print('BANNER', repr(d))
        for step in steps:
            if step[0] == 'send':
                s.sendall(step[1])
                time.sleep(0.2)
            elif step[0] == 'wait':
                d, m = recv_until(s, step[2], step[1])
                print('RECV', repr(d), 'marker=', m)
    finally:
        s.close()

def main():
    # Baseline: choose generate MAC, send simple hex
