"""Sweep Verify MAC lengths + message lengths; also invalid menu choices and formats."""
import socket, time, os

HOST, PORT = "robust", 1337

def drain(s, quiet=0.8):
    got = b""
    eof = False
    end = time.time() + quiet
    while time.time() < end:
        try:
            d = s.recv(65536)
        except socket.timeout:
            continue
        except OSError:
            break
        if not d:
            eof = True
            break
        got += d
        end = time.time() + quiet
    return got, eof

def conn():
    s = socket.create_connection((HOST, PORT), 5)
    s.settimeout(0.3)
    b, _ = drain(s, 0.9)
    return s, b

def verify(msg_hex, mac_hex):
    s, banner = conn()
    s.sendall(b"3\n"); p1, _ = drain(s)
    s.sendall(msg_hex.encode() + b"\n"); p2, _ = drain(s)
    s.sendall(mac_hex.encode() + b"\n"); p3, eof = drain(s, 1.0)
    s.close()
    return p1, p2, p3, eof

print("### Verify: message length sweep (msg = '41'*n, mac = '00'*16)")
for n in [0, 1, 2, 4, 8, 15, 16, 17, 24, 32, 33, 48, 64, 100]:
