"""Timing analysis: does the server actually process the message before 'Sorry.'?"""
import socket, time

HOST, PORT = "robust", 1337

def recv_all(s, quiet=0.5, hard=5.0):
    got = b""
    t0 = time.perf_counter()
    first = None
    end = t0 + hard
    last = t0
    while time.perf_counter() < end:
        try:
            s.settimeout(0.05)
            d = s.recv(65536)
        except socket.timeout:
            if got and time.perf_counter() - last > quiet:
                break
            continue
        except OSError:
            break
        if not d:
            break
        if first is None:
            first = time.perf_counter() - t0
        got += d
        last = time.perf_counter()
    return got, first, time.perf_counter() - last

def timed_gen(nbytes):
    msg = "41" * nbytes
    s = socket.create_connection((HOST, PORT), 5)
    s.settimeout(0.3)
    # read banner
    while True:
        try:
            if not s.recv(65536):
                break
        except socket.timeout:
            break
    s.sendall(b"2\n")
    while True:
        try:
            d = s.recv(65536)
            if b"Enter message in hex:" in d:
                break
        except socket.timeout:
            pass
    t0 = time.perf_counter()
    s.sendall(msg.encode() + b"\n")
    got, first, tail = recv_all(s, quiet=0.3, hard=4.0)
    s.close()
    return first, tail, got

print("### generate timing by message length")
for n in [1, 8, 16, 32, 64, 256, 1024, 2048, 4096]:
    try:
        first, tail, got = timed_gen(n)
        print(" nbytes=%-6d first_byte=%s tail=%s resp_first_line=%r" % (
            n, ("%.4f" % first) if first is not None else None,
            ("%.4f" % tail) if tail is not None else None,
            got.split(b"\n")[0]))
    except Exception as e:
        print(" nbytes=%-6d EXC %r" % (n, e))

print("\n### verify timing by message length (mac = 00*16)")
