import (
	"debug/elf"
	"debug/gosym"
	"fmt"
	"os"
	"strings"
)

func main() {
	f, err := elf.Open(os.Args[1])
	if err != nil {
		panic(err)
	}
	var pclndata []byte
	for _, name := range []string{".gopclntab", "__gopclntab"} {
		if s := f.Section(name); s != nil {
			pclndata, _ = s.Data()
			break
		}
	}
	if pclndata == nil {
		panic("no pclntab")
	}
	text := f.Section(".text")
	lt := gosym.NewLineTable(pclndata, text.Addr)
	tab, err := gosym.NewTable(nil, lt)
	if err != nil {
		panic(err)
	}
	filter := "main."
	if len(os.Args) > 2 {
		filter = os.Args[2]
	}
	for _, fn := range tab.Funcs {
		if strings.Contains(fn.Name, filter) {
			fmt.Printf("%s %#x %#x\n", fn.Name, fn.Entry, fn.End)
		}
	}
}
