{"content": "package main

import (
	"debug/elf"
	"debug/gosym"
	"fmt"
	"os"
)

func main() {
	f, err := elf.Open(os.Args[1])
	if err != nil {
		panic(err)
	}
	var pclndata []byte
	for _, name := range []string{".gopclntab", "__gopclntab"} {
		if s := f.Section(name); s != nil {
			pclndata, _ = s.Data()
			break
		}
	}
	text := f.Section(".text")
	lt := gosym.NewLineTable(pclndata, text.Addr)
	tab, err := gosym.NewTable(nil, lt)
	if err != nil {
		panic(err)
	}
	out, _ := os.Create(os.Args[2])
	defer out.Close()
	for _, fn := range tab.Funcs {
		fmt.Fprintf(out, "%#x %#x %s\n", fn.Entry, fn.End, fn.Name)
	}
}
