{"content": "import struct, sys

data = open('/workspace/server', 'rb').read()

def v2o(v):
    # .text at vaddr 0x401000 file off 0x1000; .rodata vaddr 0x496000 file off 0x96000
    if 0x496000 <= v < 0x4d3ae0:
        return v - 0x496000 + 0x96000
    return v - 0x400000

def rd(v, n):
    o = v2o(v)
    return data[o:o+n]

def gostr(v):
    ptr, ln = struct.unpack('<QQ', rd(v, 16))
    return rd(ptr, ln).decode('utf-8', 'replace')

