import ghidra.app.script.GhidraScript;
import ghidra.app.decompiler.*;
import ghidra.program.model.address.Address;
import ghidra.program.model.listing.Function;

public class Decompile extends GhidraScript {
  public void run() throws Exception {
    DecompInterface ifc = new DecompInterface();
    ifc.openProgram(currentProgram);
    long[] addrs = {0x493ba0L, 0x493f60L, 0x4940a0L, 0x494820L};
    for (long a : addrs) {
      Address ad = currentProgram.getAddressFactory().getDefaultAddressSpace().getAddress(a);
      Function f = getFunctionAt(ad);
      if (f == null) { println("no func at "+Long.toHexString(a)); continue; }
      DecompileResults res = ifc.decompileFunction(f, 60, monitor);
      println("===== "+f.getName()+" @ "+Long.toHexString(a)+" =====");
      println(res.getDecompiledFunction().getC());
    }
  }
}
```
Ghidra headless may take a few minutes on a 1.3MB Go binary but should be fine. Note: Go binaries with weird calling conventions decompile poorly, but Convert is simple.

Actually — maybe even simpler: use r2's `pdc` on Convert. Given the structure, maybe acceptable. Let's try r2 first (faster).

`r2 -q -A -c 's 0x493ba0; af; pdc' server`. r2's analysis of a Go binary might be slow; but we can seek and `af` at address.

