class ServerProc:
    def __init__(self):
        self.p = subprocess.Popen(['./server'], stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                                  stderr=subprocess.STDOUT, cwd='/workspace')
        self.buf = b''
    def send(self, data):
        self.p.stdin.write(data)
        self.p.stdin.flush()
    def read_until(self, marker, timeout=5.0):
        end = time.time() + timeout
        while marker not in self.buf:
            if time.time() > end:
                raise TimeoutError('timeout waiting for %r, buf=%r' % (marker, self.buf[-200:]))
            r, _, _ = select.select([self.p.stdout], [], [], 0.2)
            if r:
                d = os.read(self.p.stdout.fileno(), 65536)
                if not d:
                    raise EOFError('eof, buf=%r' % (self.buf[-200:],))
                self.buf += d
        i = self.buf.index(marker) + len(marker)
        out = self.buf[:i]
        self.buf = self.buf[i:]
        return out
    def close(self):
        try:
            self.p.kill()
        except Exception:
            pass

def gen(s, msgbytes):
    s.send(b'2\n')
