HOST, PORT = 'robust', 1337

class Conn:
    def __init__(self, timeout=5.0):
        self.s = socket.create_connection((HOST, PORT), timeout)
        self.s.settimeout(timeout)
        self.buf = b''
        self.read_until(b'Enter your choice: ')
    def send(self, data):
        self.s.sendall(data)
    def read_until(self, marker, timeout=5.0):
        end = time.time() + timeout
        while marker not in self.buf:
            if time.time() > end:
                raise TimeoutError('timeout waiting %r, buf=%r' % (marker, self.buf[-300:]))
            try:
                d = self.s.recv(65536)
            except socket.timeout:
                continue
            if not d:
                raise EOFError('eof, buf=%r' % (self.buf[-300:],))
            self.buf += d
        i = self.buf.index(marker) + len(marker)
        out = self.buf[:i]
        self.buf = self.buf[i:]
        return out
    def drain(self, timeout=2.0):
        out = b''
        end = time.time() + timeout
        while time.time() < end:
            try:
                d = self.s.recv(65536)
            except socket.timeout:
                if out:
                    break
                continue
            if not d:
                break
            out += d
        return out
    def close(self):
        try:
            self.s.close()
        except Exception:
            pass

def gen(c, msg):
    c.send(b'2\n')
    c.read_until(b'hex: ')
    c.send(msg.hex().encode() + b'\n')
    out = c.read_until(b'Enter your choice: ')
    txt = out.decode('latin1')
    i = txt.find('MAC: ')
    if i < 0:
        raise RuntimeError('no MAC: %r' % txt)
    return bytes.fromhex(txt[i+5:].split('\n')[0].strip())

def verify(c, msg, tag):
    c.send(b'3\n')
    c.read_until(b'Enter message in hex: ')
    c.send(msg.hex().encode() + b'\n')
    c.read_until(b'Enter MAC in hex: ')
    c.send(tag.hex().encode() + b'\n')
    return c.drain(3.0)

